//! Text extraction, against the generated fixtures.
//!
//! These are the tests that say whether word lookup can work at all: PDFium
//! has to hand back character boxes, and the derived word and line structure
//! has to survive a real document rather than only the synthetic layout in
//! `text.rs`'s unit tests.
//!
//! Fixtures live under `target/test-pdfs` (generated by
//! `tools/generate_fixtures.py`), and PDFium is staged under `target/native`.
//! Each test skips cleanly when either is absent.

use std::path::PathBuf;

use pdfreader_pdf::engine::{PdfEngine, PdfiumEngine};
use pdfreader_pdf::{CharRange, TextPage};

/// Workspace root, derived from this crate's manifest directory.
fn workspace_root() -> PathBuf {
    // crates/pdf -> ../.. -> repo root
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("..")
        .join("..")
}

/// Locate the staged PDFium library, scanning `target/native/*`.
fn find_pdfium() -> Option<PathBuf> {
    let native = workspace_root().join("target").join("native");
    let entries = std::fs::read_dir(&native).ok()?;
    for entry in entries.flatten() {
        let dir = entry.path();
        if dir.join("pdfium.dll").exists()
            || dir.join("libpdfium.so").exists()
            || dir.join("libpdfium.dylib").exists()
        {
            return Some(dir);
        }
    }
    None
}

/// Read the first page of a fixture, or skip the test if it is not there.
fn first_page(name: &str) -> Option<TextPage> {
    let dir = find_pdfium()?;
    let path = workspace_root().join("target").join("test-pdfs").join(name);
    if !path.exists() {
        eprintln!("SKIP: fixture {name} not found");
        return None;
    }
    let mut engine = PdfiumEngine::bind(Some(&dir)).expect("pdfium should bind");
    let (handle, _) = engine.open(&path, None).expect("fixture opens");
    engine.page_text(handle, 0).ok()
}

#[test]
fn a_real_page_produces_characters_words_and_lines() {
    let Some(page) = first_page("forms.pdf") else {
        return;
    };

    assert!(!page.chars.is_empty(), "PDFium must return characters");
    assert!(!page.words.is_empty(), "words must be derived");
    assert!(!page.lines.is_empty(), "lines must be derived");

    // Every character must point at a word and a line that exist.
    for character in &page.chars {
        assert!(
            (character.word as usize) < page.words.len(),
            "char {:?} points at a word that does not exist",
            character.ch
        );
        assert!(
            (character.line as usize) < page.lines.len(),
            "char {:?} points at a line that does not exist",
            character.ch
        );
    }
}

#[test]
fn words_come_back_as_trimmed_words() {
    let Some(page) = first_page("forms.pdf") else {
        return;
    };

    let mut multi_letter = 0;
    for word in &page.words {
        let text = page.text_in(word.first_char, word.last_char);
        assert_eq!(text, text.trim(), "a word must not carry padding: {text:?}");
        if text.chars().count() > 1 {
            multi_letter += 1;
        }
    }
    assert!(
        multi_letter > 0,
        "a form fixture should have words longer than one letter"
    );
}

#[test]
fn a_point_inside_a_glyph_finds_that_glyph() {
    let Some(page) = first_page("forms.pdf") else {
        return;
    };

    // Pick a character in the middle of the page's text and ask for it back by
    // the centre of its own box.
    let index = page.chars.len() / 2;
    let character = page.chars[index];
    if character.rect.is_degenerate() {
        return;
    }
    let x = (character.rect.min_x + character.rect.max_x) / 2.0;
    let y = (character.rect.min_y + character.rect.max_y) / 2.0;

    let hit = page
        .char_at(x, y)
        .expect("the centre of a box is inside it");
    assert_eq!(page.chars[hit as usize].ch, character.ch);
}

#[test]
fn a_click_widens_to_a_whole_word_on_a_real_page() {
    let Some(page) = first_page("forms.pdf") else {
        return;
    };

    let index = page.chars.len() / 2;
    let character = page.chars[index];
    if character.rect.is_degenerate() {
        return;
    }
    let x = (character.rect.min_x + character.rect.max_x) / 2.0;
    let y = (character.rect.min_y + character.rect.max_y) / 2.0;

    let range = page
        .word_at(x, y, 6.0)
        .expect("a point on a glyph resolves to a word");
    let text = page.range_text(range);
    assert!(!text.trim().is_empty(), "the word must hold text");
    assert!(
        !text.contains(' '),
        "a word must not span a space: {text:?}"
    );
}

#[test]
fn a_range_over_several_lines_draws_one_box_per_line() {
    let Some(page) = first_page("small-3p.pdf") else {
        return;
    };
    if page.lines.len() < 2 {
        eprintln!("SKIP: fixture has fewer than two lines of text");
        return;
    }

    let range = CharRange {
        first: 0,
        last: page.chars.len() as u32,
    };
    let rects = page.range_rects(range);
    assert!(rects.len() >= 2, "one box per line, got {}", rects.len());
    assert!(
        page.range_rect(range).is_some(),
        "the whole page is a valid range"
    );
}
